diff --git a/src/simulator.hpp b/src/simulator.hpp
index 62ab916..194a5d5 100644
--- a/src/simulator.hpp
+++ b/src/simulator.hpp
@@ -12,6 +12,7 @@
 #include "hybrid/systemc_dmi_bus.hpp"
 #include "platform/memory_map.h"
