144	private:
145	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
146	  // dmactive must transition 0->1 in its own write before haltreq is honored
147	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
148	  void halt(const char* ctx)
149	  {
150	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
151	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
152	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
153	  }
154	
155	  // Halt the hart and capture the two control fields every drain path needs:
156	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
157	  // blocks are filled by the caller, so drain() and drain_with_passthrough
158	  // share one halt + prologue.
159	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
160	  {
161	    halt("StateDrain halt");
162	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
163	                                  "StateDrain DCSR") & 0x3u;
164	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
165	  }
166	
167	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
168	  // state. Abstract-only by design, same caps gate + canonical order as the
169	  // ResumeDriver restore.
170	  void drain_andes_m_ext(hybrid_state_v1& state)
171	  {
172	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
173	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
174	    if (!andes && !mext) return;
175	
176	    if (andes) {
177	#define X(field, addr, name) \
178	  if (caps_.supports_csr(addr)) \
179	    state.andes.field = read_register_64(bus_, regno_csr(addr));
180	      HYBRID_ANDES_CSR_LIST(X)
181	#undef X
182	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
183	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
184	          state.andes.pmacfg[i] =
185	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
186	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
187	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
188	          state.andes.pmaaddr[i] =
189	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
190	    }
191	    if (mext) {
192	#define X(field, addr, name) \
193	  if (caps_.supports_csr(addr)) \
194	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
195	      HYBRID_M_EXT_CSR_LIST(X)
196	#undef X
197	    }
198	  }
199	
200	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
201	  // L26: guards on the configured scratch GPA so a V drain never stores to a
202	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
203	  void dump_v_to_scratch(uint64_t vlenb)
204	  {
205	    if (scratch_gpa_ == kVScratchGpaUnset)
