209	  }
210	
211	  DmiBus& bus_;
212	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
213	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
214	};
