123	  void resume(const hybrid_state_v1& state)
124	  {
125	    if (state.magic != HYBRID_STATE_MAGIC)
126	      throw std::runtime_error("ResumeDriver::resume: bad magic");
127	    if (state.version != HYBRID_STATE_VERSION)
128	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
129	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
130	    if (state.priv == 2 || state.priv > 3)
131	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
132	
133	    // dmactive must transition 0->1 in its own write before any other
134	    // DMCONTROL bit is honored (RISC-V Debug Spec).
135	    bus_.write(kDmcontrol, kDmcontrolDmactive);
136	    request_halt();
137	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
138	
139	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
140	    // accepted (FS or VS == Off disables the extension and the hart NACKs
141	    // the writes). The drained state.mstatus may legitimately carry FS or
142	    // VS at Off (e.g. an OS context-switched the regs away before the
143	    // trigger fired) -- gating the write on the drained field skips the
144	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
145	    // write mstatus when either extension is in scope; force-OR Initial
146	    // when the drained field is Off. This enable is local to the vsim
147	    // phase; the state.mstatus written to the handoff file is left
148	    // unmodified.
