// v5: write back the WRITABLE boot-static L2C config registers via
// Program-Buffer word stores. The L2C block is MMIO, not a CSR, so each write
// is `sw x5, 0(x6)` with the register address staged in x6 and the value (low
// word) in x5. Restores ONLY the config registers the ROI can hold as plain
// state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
// Masks. The read-only Configuration Register, the side-effecting CCTL command
// registers (writing one re-issues an L2 cache op), and the write-1-clear
// error registers are captured in the record but NEVER written back.
//
// Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
// L2C region faults the Program Buffer, so unlike a tolerant CSR write this
// must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
// the caller runs this before the GPR loop, which overwrites both.
void restore_l2c(const hybrid_state_v1& state)
{
  if (!(state.flags & HYBRID_FLAG_L2C)) return;
  if (!l2c_present_) return;

  pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
                   state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]);
  pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
                   state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
  for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
    const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
    pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
  }
}

// One L2C register store: stage the MMIO address in x6 and the value's low
// word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
// per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
// L2C control bits live in the low 32.
void pb_store_l2c_reg(uint32_t offset, uint64_t value)
{
  write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
  write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
  const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
  exec_progbuf(bus_, std::span<const uint32_t>{pb});
}

